import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from 'src/environments/environment';
import { HttpClient, HttpHeaders } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})
export class ReferralService {
  constructor(private http: HttpClient) {}

  getReferralData(): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.get<any>(`${environment.BACKEND_URL}/admin/refferal`, { headers });
  }
  
  updateReferralData(profileData: any): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.patch<any>(`${environment.BACKEND_URL}/admin/refferal/1`, profileData, { headers });
  }
  getReferralPointsData(): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.get<any>(`${environment.BACKEND_URL}/admin/refferal-points`, { headers });
  }
  getBatchPointsData(): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.get<any>(`${environment.BACKEND_URL}/admin/badge-points`, { headers });
  }


  updateReferralPointsData(profileData: any): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.patch<any>(`${environment.BACKEND_URL}/admin/refferal-points/1`, profileData, { headers });
  }
  updateBatchPointsData(batchData: any): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.put<any>(`${environment.BACKEND_URL}/admin/badge-points`, batchData, { headers });
  }

  getAllBadges(): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.get<any>(`${environment.BACKEND_URL}/admin/badge`, { headers });
  }

  createBadge(badgeData: any): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.post<any>(`${environment.BACKEND_URL}/admin/badge`, badgeData, { headers });
  }

  updateBadge(badgeId: string, badgeData: any): Observable<any> {
    const token = localStorage.getItem('authToken'); // Retrieve token
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.patch<any>(`${environment.BACKEND_URL}/admin/badge/${badgeId}`, badgeData, { headers });
  }

  updateBadgeRanks(badges: any[]): Observable<any> {
    const token = localStorage.getItem('authToken');
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.put<any>(`${environment.BACKEND_URL}/admin/badge-points/ranks`, { badges }, { headers });
  }
}
